<script setup>import {ref} from 'vue';import {Head,useForm} from '@inertiajs/vue3';import Errors from '../Components/Errors.vue';import {date} from '../lib/labels';defineProps({users:Array,communes:Array,localities:Array,logs:Array});const editing=ref(null);function edit(u){editing.value=u.id;f.name=u.name;f.email=u.email;f.password='';f.role=u.role;f.commune_id=u.commune_id||'';f.phone=u.profile?.phone||'';f.skills=u.profile?.skills?.join(', ')||'';f.referenced=u.profile?.referenced||false;window.scrollTo({top:0,behavior:'smooth'});}function save(){f.post('/administration/comptes'+(editing.value?'/'+editing.value:''),{onSuccess:()=>{editing.value=null;f.reset()}})}const f=useForm({name:'',email:'',password:'',role:'gestionnaire',commune_id:'',phone:'',skills:'',referenced:false}),l=useForm({name:'',commune_id:''});</script><template><Head title="Administration"/><div class="page-heading"><span class="eyebrow">ORGANISER LES ACCÈS ET LE TERRITOIRE</span><h1>Administration</h1><p>Comptes professionnels, référentiels et traçabilité.</p></div><div class="grid two"><form class="card form-stack" @submit.prevent="save"><h3>{{editing?'Modifier le compte':'Créer un compte'}}</h3><Errors :errors="f.errors"/><label>Nom<input v-model="f.name" required></label><label>E-mail<input type="email" v-model="f.email" required></label><label>Mot de passe initial<input type="password" v-model="f.password" :required="!editing" minlength="12" autocomplete="new-password"></label><label>Rôle<select v-model="f.role"><option value="gestionnaire">Gestionnaire</option><option value="relais">Relais communautaire</option><option value="technicien">Technicien</option><option value="usager">Usager / école</option><option value="admin">Administrateur</option></select></label><label>Commune<select v-model="f.commune_id" required><option value="" disabled>Choisir</option><option v-for="c in communes" :key="c.id" :value="c.id">{{c.name}}</option></select></label><template v-if="f.role==='technicien'"><label>Téléphone<input v-model="f.phone" required></label><label>Compétences séparées par des virgules<input v-model="f.skills" required></label><label class="checkbox"><input type="checkbox" v-model="f.referenced">Référencement vérifié par la coordination</label></template><button class="btn btn-primary" :disabled="f.processing">{{editing?'Enregistrer les modifications':'Créer le compte'}}</button><button v-if="editing" type="button" class="btn btn-outline" @click="editing=null;f.reset()">Annuler</button></form><section class="form-stack"><form class="card form-stack" @submit.prevent="l.post('/administration/localites',{onSuccess:()=>l.reset()})"><h3>Ajouter une commune ou une localité</h3><Errors :errors="l.errors"/><label>Commune de rattachement<select v-model="l.commune_id"><option value="">Créer une nouvelle commune</option><option v-for="c in communes" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Nom<input v-model="l.name" required></label><button class="btn btn-primary" :disabled="l.processing">Enregistrer</button></form><article class="card"><h3>Comptes enregistrés</h3><div v-for="u in users" :key="u.id" class="list-row"><span class="avatar">{{u.name[0]}}</span><div><strong>{{u.name}}</strong><small>{{u.email}}</small></div><span class="badge">{{u.role}}</span><button class="text-link" @click="edit(u)">Modifier</button></div></article></section></div><section class="card mt"><h3>Journal d’audit</h3><div v-for="a in logs" :key="a.id" class="list-row"><span>{{date(a.created_at)}}</span><strong>{{a.action}}</strong><span>{{a.subject}}</span></div><p v-if="!logs.length" class="empty">Aucune action enregistrée.</p></section></template>
